    $trackColor = [System.Drawing.Color]::FromArgb(238, 241, 245)
    $twoPi = 2 * [math]::PI
    $drawBar = { param($P, $G)
      # Thin rounded bars with no border (the Administrator, 2026-11-14, layout P1): a light track and the fill on top.
