        if ($gr -ne $groups[0] -and $colR.RowCount) { $gap = New-Object System.Windows.Forms.Panel; $gap.Height = & $sc 16; $gap.Margin = New-Object System.Windows.Forms.Padding(0); & $stackAdd $colR $gap }
